      "content": "{\n  \"name\": \"dsh-im-gateway\",\n  \"version\": \"0.3.3\",\n  \"description\": \"聚合 IM 网关插件（DeepSeek Harness）：把 dsh agent 接入微信、飞书、钉钉、企业微信、QQ、Telegram、Discord、Slack、WhatsApp 等 25+ 渠道，统一会话路由、审批桥、交互提问、定时提醒、白名单与扫码接入。\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"client.js\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"docs\",\n    \"assets\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json && node -e \\\"require('node:fs').copyFileSync('client.js','lib/client.js')\\\"\",\n    \"prepublishOnly\": \"npm run typecheck && npm test\",\n    \"prepack\": \"npm run build\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\",\n    \"test\": \"node --test tests/*.test.mjs\"\n  },\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"qrcode\": \"^1.5.4\"\n  },\n  \"optionalDependencies\": {\n    \"@larksuiteoapi/node-sdk\": \"^1.73.0\",\n    \"@tencent-connect/qqbot-connector\": \"^1.2.0\",\n    \"@wecom/aibot-node-sdk\": \"^1.0.7\",\n    \"@whiskeysockets/baileys\": \"^6.7.18\",\n    \"dingtalk-stream\": \"^2.1.4\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-agent\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-agent-presets\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-attachment\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-jobs\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\":