    {
      "path": "lib/core/router.js",
      "content": "/**\n * 会话路由：管理 (渠道, chat) → agent 会话的映射与生命周期。\n * - per-chat 模式：网关用 ctx.agents.create 为每个 chat 创建独立 agent 会话，\n *   `/new` 轮换（dispose 旧的，建新的）。\n * - bound 模式：不创建 agent；用户 `/bind <session-id>` 绑定本进程 live 的 agent。\n * @module dsh-im-gateway/core/router\n */\nimport { SessionId } from '@deepseek-ai/dsh-session';\nexport class SessionRouter {\n    ctx;\n    options;\n    entries = new Map();\n    /** sessionId → 绑定它的 chat 集合（bound 模式可多 chat 绑同一会话）。 */\n    bySession = new Map();\n    /** 每 chat 的工作区偏好（/workspace 设置，持久化由网关层负责）。 */\n    workspaces = new Map();\n    /** chat 最后绑定的会话（持久化，重启恢复）。 */\n    chatSessions = new Map();\n    constructor(ctx, options) {\n        this.ctx = ctx;\n        this.options = options;\n        for (const [key, sid] of Object.entries(options.chatSessionStore?.load() ?? {}))\n            this.chatSessions.set(key, sid);\n    }\n    /** 恢复持久化的工作区偏好（启动时由网关层灌入）。 */\n    restoreWorkspaces(entries) {\n        for (const [key, path] of entries)\n            this.workspaces.set(key, path);\n    }\n    /** 当前 chat 的工作区偏好（无则全局 cwd）。 */\n    workspaceOf(channelId, chatId) {\n        return this.workspaces.get(`${channelId}:${chatId}`);\n    }\n    /** 设置 chat 的工作区偏好，返回旧值。 */\n    setWorkspace(channelId, chatId, path) {\n        const key = `${channelId}:${chatId}`;\n        const old = this.workspaces.get(key);\n        this.workspaces.set(key, path);\n        return old;\n    }\n    /** 全部工作区偏好（持久化用）。 */\n    workspaceEntries() {\n        return [...this.workspaces.entries()];\n    }\n    /** 取 chat 条目；不存在时返回 undefined（调用方决定是否创建）。 */\n    get(channelId, chatId) {\n        return this.entries.get(`${channelId}:${chatId}`);\n    }\n    /** per-chat 模式：取或建（优先恢复该 chat 上次的会话，否则创建新会话）。 */\n    async getOrCreate(channelId, chatId) {\n        const key = `${channelId}:${chatId}`;\n        const existing = this.entries.get(key);\n        if (existing)\n            return existing;\n        // 重启恢复：上次绑定的会话仍存在则继续它（resume/复用 live），否则新建\n        const last = this.chatSessions.get(key);\n        if (last) {\n            const restored = await this.continueSession(channelId, chatId, last);\n            if (restored.ok)\n                return this.entries.get(key);\n        }\n        return this.create(channelId, chatId);\n    }\n    /** 记录 chat 当前绑定的会话（持久化，重启后恢复）。 */\n    recordChatSession(channelId, chatId, sessionId) {\n        const key = `${channelId}:${chatId}`;\n        this.chatSessions.set(key, sessionId);\n        this.options.chatSessionStore?.save(Object.fromEntries(this.chatSessions));\n    }\n    /** 该 chat 上次绑定的会话（无则 undefined；供命令路径恢复用）。 */\n    lastSessionOf(channelId, chatId) {\n        return this.chatSessions.get(`${channelId}:${chatId}`);\n    }\n    /** 创建新会话（per-chat；cwd 优先 chat 工作区偏好）。 */\n    async create(channelId, chatId) {\n        const key = `${channelId}:${chatId}`;\n        const sessionId = SessionId(`im:${channelId}:${chatId}:${Date.now()}`);\n        const cwd = this.workspaces.get(key) ?? this.options.cwd;\n        const handle = await this.ctx.agents.create({\n            sessionId,\n            meta: { cwd },\n            agentOptions: { provider: this.options.provider, model: this.options.model },\n            setup: this.presetSetup(this.options.agentPreset),\n        });\n        await this.attachToWorkspace(cwd, sessionId);\n        const entry = { channelId, chatId, key, sessionId: String(sessionId), handle, workspace: cwd };\n        this.entries.set(key, entry);\n        this.index(entry);\n        this.recordChatSession(channelId, chatId, String(sessionId));\n        return entry;\n    }\n    /** 把新会话登记到宿主 Workspace Registry，确保 Web 侧按目录分组。 */\n    async attachToWorkspace(cwd, sessionId) {\n        let registry;\n        try {\n            registry = this.ctx.workspaceRegistry;\n        }\n        catch {\n            // Older hosts do not inject the optional workspace registry.\n            return;\n        }\n        if (!registry)\n            return;\n        try {\n            const workspace = await registry.resolveByPath(cwd) ?? await registry.create(cwd);\n            await workspace.attachSession(sessionId);\n        }\n        catch (err) {\n            this.options.log?.(`[gateway] 会话 ${sessionId} 挂载工作区失败: ${err instanceof Error ? err.message : String(err)}`);\n        }\n    }\n    /** Agent setup：把 agent scope 挂入 preset（否则工具/prompt/skills 只有全局层，\n     * 缺失 bash/fs/web 等核心工具）。\n     */\n    presetSetup(presetId) {\n        const ctx = this.ctx;\n        return async (agentCtx) => {\n            await ctx.agentPresets.mount(agentCtx, presetId);\n        };\n    }\n    /** 解析会话的 agentPreset（header 记录；未知时用默认）。 */\n    async presetOf(sessionId) {\n        try {\n            const query = this.ctx.sessionQuery;\n            if (query) {\n                const records = await query.filterSessions([{ kind: 'id', values: [SessionId(sessionId)] }]);\n                const header = records[0]?.header;\n                if (header?.agentPreset)\n                    return header.agentPreset;\n            }\n        }\n        catch { /* 未知则用默认 */ }\n        return this.options.agentPreset;\n    }\n    /**\n     * 继续已有会话（per-chat）：优先复用本进程 live agent，否则 resume 持久化会话。\n     * 成功时把 chat 条目切换到该会话。\n     */\n    async continueSession(channelId, chatId, sessionId) {\n        const key = `${channelId}:${chatId}`;\n        const existing = this.entries.get(key);\n        // 本进程已有 live agent（其他 chat 正在用或本 chat 的旧条目）\n        let liveAgent = this.ctx.agents.get(SessionId(sessionId));\n        if (!liveAgent) {\n            try {\n                // 必须带 agentOptions（provider/model）与 setup（挂入 preset），否则\n                // prompt 缺 {{model}} 变量、且工具只剩全局层（无 bash/fs/web 等核心工具）\n                const preset = await this.presetOf(sessionId);\n                const handle = await this.ctx.agents.resume({\n                    resumeSessionId: SessionId(sessionId),\n                    agentOptions: { provider: this.options.provider, model: this.options.model },\n                    setup: this.presetSetup(preset),\n                });\n                if (existing?.handle) {\n                    this.unindex(existing);\n                    await existing.handle.dispose().catch(() => undefined);\n                }\n                const entry = { channelId, chatId, key, sessionId, handle };\n                this.entries.set(key, entry);\n                this.index(entry);\n                this.recordChatSession(channelId, chatId, sessionId);\n                return { ok: true, workspace: sessionCwdOf(handle.agent) };\n            }\n            catch (err) {\n                return { ok: false, error: `继续会话失败：${err instanceof Error ? err.message : String(err)}` };\n            }\n        }\n        // live agent 复用：本 chat 条目指向它（释放旧 handle；agent 引用供注入，不 dispose）\n        if (existing?.handle && existing.sessionId !== sessionId) {\n            this.unindex(existing);\n            await existing.handle.dispose().catch(() => undefined);\n        }\n        const entry = { channelId, chatId, key, sessionId, agent: liveAgent, boundBy: undefined };\n        this.entries.set(key, entry);\n        this.index(entry);\n        this.recordChatSession(channelId, chatId, sessionId);\n        return { ok: true, workspace: sessionCwdOf(liveAgent) };\n    }\n    /** `/new`：解绑旧条目并始终创建新会话。 */\n    async rotate(channelId, chatId) {\n        const key = `${channelId}:${chatId}`;\n        const old = this.entries.get(key);\n        if (old) {\n            this.unindex(old);\n            this.entries.delete(key);\n            if (old.handle)\n                await old.handle.dispose().catch(() => undefined);\n        }\n        return this.create(channelId, chatId);\n    }\n    /** bound 模式：把 chat 绑定到本进程的 live agent 会话。 */\n    bind(channelId, chatId, sessionId, userId) {\n        const agent = this.ctx.agents.get(SessionId(sessionId));\n        if (!agent)\n            return { ok: false, error: `会话 ${sessionId} 当前没有运行中的 agent（须为本进程 live 会话）` };\n        const key = `${channelId}:${chatId}`;\n        const existing = this.entries.get(key);\n        if (existing?.handle) {\n            // per-chat 条目转 bound：释放自建 handle\n            this.unindex(existing);\n            void existing.handle.dispose().catch(() => undefined);\n        }\n        const entry = { channelId, chatId, key, sessionId, boundBy: userId };\n        this.entries.set(key, entry);\n        this.index(entry);\n        return { ok: true };\n    }\n    /** 解绑（bound 模式回到无绑定状态）。 */\n    unbind(channelId, chatId) {\n        const key = `${channelId}:${chatId}`;\n        const entry = this.entries.get(key);\n        if (entry) {\n            this.unindex(entry);\n            this.entries.delete(key);\n        }\n    }\n    /** 按 sessionId 找所有关联 chat（事件路由用）。 */\n    chatsForSession(sessionId) {\n        return [...(this.bySession.get(sessionId) ?? [])];\n    }\n    /** 全部条目（/status 用）。 */\n    list() {\n        return [...this.entries.values()];\n    }\n    /** 插件卸载时释放所有自建 agent。 */\n    async disposeAll() {\n        const handles = [...this.entries.values()].filter((e) => e.handle).map((e) => e.handle);\n        this.entries.clear();\n        this.bySession.clear();\n        await Promise.allSettled(handles.map((h) => h.dispose()));\n    }\n    index(entry) {\n        let set = this.bySession.get(entry.sessionId);\n        if (!set) {\n            set = new Set();\n            this.bySession.set(entry.sessionId, set);\n        }\n        set.add(entry);\n    }\n    unindex(entry) {\n        const set = this.bySession.get(entry.sessionId);\n        if (set) {\n            set.delete(entry);\n            if (set.size === 0)\n                this.bySession.delete(entry.sessionId);\n        }\n    }\n}\n/** 从 agent 的会话 header 取工作目录（可能没有）。 */\nfunction sessionCwdOf(agent) {\n    return agent.session.header?.cwd;\n}\n//# sourceMappingURL=router.js.map"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-im-gateway：DeepSeek Harness 聚合 IM 网关插件。\n *\n * 把 dsh agent 接入 20+ 聊天渠道（Telegram / Discord / Slack / 飞书 / 微信 /\n * QQ / WhatsApp / Signal / Teams / LINE / Matrix / Mattermost / Google Chat /\n * IRC / Twitch / Nostr / Nextcloud Talk / Synology Chat / Zalo / iMessage …），\n * 统一提供：每聊天一个 agent 会话、/new /status /bind 等命令、审批远程应答、\n * ask_user_question 交互提问桥、手机多段输入合并、长回复分片、白名单、媒体收发。\n *\n * 两种配置方式：\n * 1. Web GUI 设置面板「IM 网关」：点选渠道 → 扫码/填凭据 → 立即连接（无需重启）\n * 2. profile 的 cordis.patch.yml 写 im-gateway 行 config（或环境变量）\n *\n * @module dsh-im-gateway\n */\nimport Schema from '@deepseek-ai/schemastery';\nimport { ImGateway } from './core/gateway.js';\nimport { CronRegistry } from './core/cron.js';\nimport { ChannelManager } from './manager.js';\nimport { homedir } from 'node:os';\nimport { join } from 'node:path';\nimport { mkdirSync, readFileSync, writeFileSync } from 'node:fs';\nimport { acquireDshHomeInstanceLock } from './instance-lock.js';\nexport const name = 'dsh-im-gateway';\n// agents：创建/查找 agent 会话；jobs：后台任务（扫码/轮询状态对 Web UI 可见）；\n// tools：注册 im_send_file（agent → IM 发文件）；attachments：图片入站转 image block；\n// webServer：提供设置面板调用的 HTTP API；agentPresets：创建/继续 agent 时挂入 preset；\n// workspaceRegistry：把 IM 新会话挂入 Web 端对应工作区分组\nexport const inject = ['agents', 'jobs', 'tools', 'attachments', 'webServer', 'sessionQuery', 'agentPresets', 'userQuestions', 'workspaceRegistry'];\n/** 网关部署配置。 */\nexport const Config = Schema.object({\n    // 渠道配置用宽松 dict：任意渠道字段（token/appId 等）原样保留，按渠道读取\n    channels: Schema.dict(Schema.any()).default({}),\n    sessionMode: Schema.union(['per-chat', 'bound']).default('per-chat'),\n    cwd: Schema.string().default(process.cwd()),\n    provider: Schema.string().default('deepseek-official'),\n    model: Schema.string().default('deepseek-v4-flash'),\n    agentPreset: Schema.string().default('standard'),\n    // 默认放行所有用户（个人/小团队开箱即用）；需要管控时改为 false 并配置白名单\n    allowAllUsers: Schema.boolean().default(true),\n    allowedUserIds: Schema.dict(Schema.array(Schema.string())).default({}),\n    mergeTimeoutSecs: Schema.number().default(5),\n    longInputAckChars: Schema.number().default(180),\n    approvalTimeoutSecs: Schema.number().default(120),\n    questionTimeoutSecs: Schema.number().default(600),\n    summaryOnTurnEnd: Schema.boolean().default(true),\n    // im_cron：聊天级定时任务（绑定 chatId，与会话轮换无关）\n    cronTickIntervalSecs: Schema.number().default(30),\n    cronMaxConcurrent: Schema.number().default(2),\n    cronCatchUp: Schema.boolean().default(false),\n    stateDir: Schema.string().default(''),\n});\n/**\n * 启动聚合网关。\n * @param ctx - Cordis 上下文；声明注入的服务。\n * @param config - 部署配置。\n */\nexport function apply(ctx, config) {\n    const dshHome = process.env.DSH_HOME ?? join(homedir(), '.dsh');\n    const instanceLock = acquireDshHomeInstanceLock(dshHome);\n    try {\n        ctx.effect(() => () => instanceLock.release(), 'im-gateway.instance-lock');\n    }\n    catch (error) {\n        instanceLock.release();\n        throw error;\n    }\n    const stateDir = config.stateDir !== ''\n        ? config.stateDir\n        : join(dshHome, 'dsh-im-gateway');\n    mkdirSync(stateDir, { recursive: true });\n    // 环形日志缓冲：Web UI 的 jobs readOutput 可读（扫码链接等），同时落盘便于排查\n    const recent = [];\n    const rawLog = ctx.logger(name);\n    const logFile = join(stateDir, 'gateway.log');\n    const log = (line) => {\n        const stamped = `${new Date().toISOString()} ${line}`;\n        recent.push(stamped);\n        if (recent.length > 300)\n            recent.splice(0, recent.length - 300);\n        rawLog.info(line);\n        try {\n            writeFileSync(logFile, `${stamped}\\n`, { flag: 'a' });\n        }\n        catch { /* 日志失败不影响运行 */ }\n    };\n    // 每聊天工作区偏好持久化（/workspace 命令）\n    const workspaceFile = join(stateDir, 'workspaces.json');\n    const workspaceStore = {\n        load: () => {\n            try {\n                const parsed = JSON.parse(readFileSync(workspaceFile, 'utf8'));\n                return Array.isArray(parsed) ? parsed : [];\n            }\n            catch {\n                return [];\n            }\n        },\n        save: (entries) => {\n            try {\n                mkdirSync(stateDir, { recursive: true });\n                writeFileSync(workspaceFile, JSON.stringify(entries, null, 2));\n            }\n            catch (err) {\n                log(`[manager] 工作区状态落盘失败: ${err instanceof Error ? err.message : String(err)}`);\n            }\n        },\n    };\n    // 会话标题缓存持久化（/sessions 列表兜底显示）\n    const titleFile = join(stateDir, 'session-titles.json');\n    const titleStore = {\n        load: () => {\n            try {\n                const parsed = JSON.parse(readFileSync(titleFile, 'utf8'));\n                return parsed && typeof parsed === 'object' ? parsed : {};\n            }\n            catch {\n                return {};\n            }\n        },\n        save: (titles) => {\n            try {\n                mkdirSync(stateDir, { recursive: true });\n                writeFileSync(titleFile, JSON.stringify(titles, null, 2));\n            }\n            catch (err) {\n                log(`[manager] 标题缓存落盘失败: ${err instanceof Error ? err.message : String(err)}`);\n            }\n        },\n    };\n    // 会话最后活动时间持久化（/sessions 按活动排序）\n    const activityFile = join(stateDir, 'last-activity.json');\n    const activityStore = {\n        load: () => {\n            try {\n                const parsed = JSON.parse(readFileSync(activityFile, 'utf8'));\n                return parsed && typeof parsed === 'object' ? parsed : {};\n            }\n            catch {\n                return {};\n            }\n        },\n        save: (activity) => {\n            try {\n                mkdirSync(stateDir, { recursive: true });\n                writeFileSync(activityFile, JSON.stringify(activity, null, 2));\n            }\n            catch (err) {\n                log(`[manager] 活动时间落盘失败: ${err instanceof Error ? err.message : String(err)}`);\n            }\n        },\n    };\n    // 每 chat 最后绑定的会话持久化（重启后自动恢复上次会话）\n    const chatSessionFile = join(stateDir, 'chat-sessions.json');\n    const chatSessionStore = {\n        load: () => {\n            try {\n                const parsed = JSON.parse(readFileSync(chatSessionFile, 'utf8'));\n                return parsed && typeof parsed === 'object' ? parsed : {};\n            }\n            catch {\n                return {};\n            }\n        },\n        save: (sessions) => {\n            try {\n                mkdirSync(stateDir, { recursive: true });\n                writeFileSync(chatSessionFile, JSON.stringify(sessions, null, 2));\n            }\n            catch (err) {\n                log(`[manager] 会话绑定落盘失败: ${err instanceof Error ? err.message : String(err)}`);\n            }\n        },\n    };\n    const gateway = new ImGateway(ctx, { config, stateDir, log, workspaceStore, titleStore, activityStore, chatSessionStore });\n    // im_cron：聊天级定时任务（绑定 chatId，与会话轮换无关）\n    const cron = new CronRegistry({\n        stateDir,\n        log,\n        catchUp: config.cronCatchUp,\n        send: async (channelId, chatId, text) => {\n            const channel = gateway.channel(channelId);\n            if (!channel)\n                return false;\n            try {\n                await channel.send(chatId, text);\n                return true;\n            }\n            catch (err) {\n                log(`[cron] ${channelId} 发送失败: ${err instanceof Error ? err.message : String(err)}`);\n                return false;\n            }\n        },\n    });\n    gateway.setCronRegistry(cron);\n    const manager = new ChannelManager(ctx, { config, stateDir, log, gateway, cron });\n    // 未授权用户 → 登记待授权请求（设置面板可一键批准，无需手动找用户 ID）\n    gateway.setUnauthorizedHandler((channelId, msg) => {\n        manager.requestAuthorization(channelId, msg.userId ?? '(匿名)', msg.username, msg.chatId);\n        return '⛔ 未授权：请让管理员在 dsh 设置 → IM 网关 中批准你的访问请求。';\n    });\n    // im_cron tick：独立 effect，热重载时定时器随 effect 清理，不会残留双 tick\n    ctx.effect(() => {\n        const timer = setInterval(() => {\n            void cron.tick();\n        }, Math.max(1, config.cronTickIntervalSecs) * 1000);\n        timer.unref?.();\n        return () => {\n            clearInterval(timer);\n            cron.dispose();\n        };\n    }, 'im-gateway.cron');\n    ctx.effect(() => {\n        // 启动已启用渠道（channels.json / cordis 配置）\n        void manager.initAll().then(() => {\n            const running = manager.list().filter((c) => c.running);\n            log(`网关启动完成：${running.length} 个渠道运行中（${running.map((c) => c.id).join(', ') || '无'}）`);\n        });\n        manager.registerApi();\n        return () => {\n            manager.disposeApi();\n            void manager.disconnectAll();\n            gateway.dispose();\n            void gateway.stopAgents();\n        };\n    }, 'im-gateway.serve');\n    // 后台任务：让 Web UI 能看到网关状态与扫码链接\n    ctx.jobs.attachController(name);\n    ctx.jobs.start({\n        kind: 'im-gateway',\n        label: 'IM 网关（设置面板可快速连接渠道）',\n        run: () => {\n            const timer = setInterval(() => {\n                // 保持任务活跃；状态通过 readOutput 暴露\n            }, 60_000);\n            timer.unref?.();\n            return {\n                cancel: () => clearInterval(timer),\n                done: Promise.resolve({ status: 'completed' }),\n                readOutput: () => recent.splice(0).join('\\n'),\n            };\n        },\n    });\n}\nexport * from './core/types.js';\nexport * from './core/gateway.js';\nexport * from './channels/index.js';\nexport * from './manager.js';\n//# sourceMappingURL=index.js.map"
    },
    {
      "path": "lib/manager.js",
      "content": "/**\n * 渠道管理器：UI 驱动的渠道生命周期（启用/停用/刷新二维码/状态查询）。\n *\n * - 持久化：`$DSH_HOME/dsh-im-gateway/channels.json`（UI 配置优先于 cordis config）\n * - 动态启停：无需重启 dsh，点「连接」即生效\n * - HTTP API：`/dsh-im-gateway/api/*`（Web GUI 面板调用）\n * @module dsh-im-gateway/manager\n */\nimport { mkdirSync, readFileSync, writeFileSync } from 'node:fs';\nimport { join, dirname } from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { provisionerFor } from './core/provisioning.js';\nimport { CHANNEL_IDS, CHANNEL_META, createChannel } from './channels/index.js';\n/** 本模块目录（ESM 无 __dirname；lib/manager.js 的 ../assets 即包根 assets）。 */\nconst MODULE_DIR = dirname(fileURLToPath(import.meta.url));\nconst TERMINAL_PROVISIONING = new Set(['已连接', '已取消']);\nconst FAILED_PROVISIONING = new Set(['扫码失败', '扫码启动失败', '连接失败', '二维码已过期']);\nexport function normalizeChannelStatus(input) {\n    const provisioning = input.provisioningStatus ?? '';\n    if (FAILED_PROVISIONING.has(provisioning))\n        return '异常';\n    if (provisioning && !TERMINAL_PROVISIONING.has(provisioning))\n        return '连接中';\n    if (!input.running)\n        return '未连接';\n    const raw = input.rawStatus ?? '';\n    if (/错误|失败|异常|缺少依赖|已断开|已停止|已登出|仅支持/.test(raw))\n        return '异常';\n    if (input.loginUrl || /等待|登录中|连接中|重连中|鉴权中|握手|未启动/.test(raw))\n        return '连接中';\n    return '已连接';\n}\nexport class ChannelManager {\n    ctx;\n    options;\n    stateFile;\n    cron;\n    store;\n    /** 渠道级白名单（UI 批准的用户）：channelId → userId[]。 */\n    allowlist;\n    /** 待授权请求：channelId → 请求列表。 */\n    pending;\n    /** 运行中的 adapter：id → { adapter }。 */\n    running = new Map();\n    /** 官方扫码接入尝试：同一渠道最多一个。 */\n    provisioning = new Map();\n    /** API 路由 disposer（HMR 重载/卸载时清理，避免重复注册）。 */\n    apiDisposers = [];\n    constructor(ctx, options) {\n        this.ctx = ctx;\n        this.options = options;\n        this.cron = options.cron;\n        this.stateFile = join(options.stateDir, 'channels.json');\n        const loaded = this.load();\n        this.store = loaded.channels;\n        this.allowlist = loaded.allowlist;\n        this.pending = loaded.pending;\n    }\n    load() {\n        try {\n            const raw = readFileSync(this.stateFile, 'utf8');\n            const parsed = JSON.parse(raw);\n            return {\n                channels: parsed.channels ?? {},\n                allowlist: parsed.allowlist ?? {},\n                pending: parsed.pending ?? {},\n            };\n        }\n        catch {\n            return { channels: {}, allowlist: {}, pending: {} };\n        }\n    }\n    flush() {\n        try {\n            mkdirSync(this.options.stateDir, { recursive: true });\n            writeFileSync(this.stateFile, JSON.stringify({ channels: this.store, allowlist: this.allowlist, pending: this.pending }, null, 2));\n        }\n        catch (err) {\n            this.options.log(`[manager] 状态落盘失败: ${err instanceof Error ? err.message : String(err)}`);\n        }\n    }\n    // ── 授权 ─────────────────────────────────────────────────────\n    /** 该用户是否已获授权（UI allowlist 或 cordis 配置白名单）。 */\n    isAuthorized(channelId, userId) {\n        if (this.options.config.allowAllUsers)\n            return true;\n        const fromAllowlist = this.allowlist[channelId];\n        if (fromAllowlist && fromAllowlist.includes(userId))\n            return true;\n        const perChannel = this.options.config.allowedUserIds[channelId];\n        if (perChannel && perChannel.includes(userId))\n            return true;\n        const global = this.options.config.allowedUserIds['*'];\n        if (global && global.includes(userId))\n            return true;\n        return false;\n    }\n    /** 记录一个待授权请求（去重）。 */\n    requestAuthorization(channelId, userId, username, chatId) {\n        const list = this.pending[channelId] ?? [];\n        if (!list.some((p) => p.userId === userId)) {\n            list.push({ userId, username, chatId, time: Date.now() });\n            this.pending[channelId] = list;\n            this.flush();\n            this.options.log(`[manager] ${channelId} 有待授权请求：${username ?? userId}`);\n        }\n    }\n    /** 批准用户：加入渠道白名单并同步网关。 */\n    approve(channelId, userId) {\n        const list = this.allowlist[channelId] ?? [];\n        if (!list.includes(userId)) {\n            list.push(userId);\n            this.allowlist[channelId] = list;\n        }\n        this.options.gateway.addAuthorizedUser(channelId, userId);\n        this.removePending(channelId, userId);\n        this.flush();\n        this.options.log(`[manager] 已授权 ${channelId} 用户 ${userId}`);\n        return { ok: true };\n    }\n    /** 拒绝用户：仅移除待授权请求。 */\n    deny(channelId, userId) {\n        this.removePending(channelId, userId);\n        this.flush();\n    }\n    removePending(channelId, userId) {\n        const list = this.pending[channelId];\n        if (!list)\n            return;\n        this.pending[channelId] = list.filter((p) => p.userId !== userId);\n        if (this.pending[channelId].length === 0)\n            delete this.pending[channelId];\n    }\n    /** 全部待授权请求（跨渠道聚合，UI 横幅用）。 */\n    pendingRequests() {\n        const out = [];\n        for (const [channelId, list] of Object.entries(this.pending)) {\n            for (const p of list)\n                out.push({ channelId, userId: p.userId, username: p.username, time: p.time });\n        }\n        return out;\n    }\n    /** 合并配置：channels.json（UI）优先，cordis config 兜底。 */\n    mergedConfig(id) {\n        const cordis = this.options.config.channels[id] ?? {};\n        return { ...cordis, ...(this.store[id] ?? {}) };\n    }\n    /** 启动时初始化：合并配置中应启用的渠道全部启动；并把持久化白名单灌入网关。 */\n    async initAll() {\n        // 重启后恢复 UI 批准的渠道白名单\n        for (const [channelId, users] of Object.entries(this.allowlist)) {\n            for (const userId of users)\n                this.options.gateway.addAuthorizedUser(channelId, userId);\n        }\n        for (const id of CHANNEL_IDS) {\n            const cfg = this.mergedConfig(id);\n            // 启用判定：cordis enabled=true，或 store 存在且未被显式禁用\n            // （断开只停运行态不写 enabled，因此\"配置了 = 重启自动恢复\"）\n            const stored = this.store[id];\n            const enabled = cfg.enabled === true || (stored !== undefined && stored.enabled !== false);\n            if (enabled) {\n                await this.connect(id).catch((err) => {\n                    this.options.log(`[manager] ${id} 启动失败: ${err instanceof Error ? err.message : String(err)}`);\n                });\n            }\n        }\n    }\n    /** 持久化白名单条目（重启恢复用）。 */\n    allowlistEntries() {\n        return Object.entries(this.allowlist);\n    }\n    /** 启用并启动一个渠道。extra 里的字段合并进配置并持久化。 */\n    async connect(id, extra) {\n        const meta = CHANNEL_META[id];\n        if (!meta)\n            return { ok: false, error: `未知渠道 ${id}` };\n        // 合并 extra → store\n        if (extra) {\n            this.store[id] = { ...(this.store[id] ?? {}), ...extra, enabled: true };\n            this.flush();\n        }\n        const cfg = this.mergedConfig(id);\n        if (this.running.has(id)) {\n            // 已运行：extra 变更时先停再启\n            await this.disconnect(id);\n        }\n        const adapter = createChannel(id, { ...cfg, enabled: true }, this.options.log, this.options.stateDir);\n        if (!adapter) {\n            const error = `${meta.label}：缺少必要配置（${meta.needs.join(' / ') || '未知原因'}）`;\n            this.options.log(`[manager] ${id} 连接失败: ${error}`);\n            return { ok: false, error };\n        }\n        this.options.gateway.register(adapter);\n        this.running.set(id, adapter);\n        try {\n            await adapter.start();\n            this.options.log(`[manager] ${id} 已连接`);\n            return { ok: true };\n        }\n        catch (err) {\n            this.running.delete(id);\n            this.options.gateway.unregister(id);\n            const error = `${meta.label} 启动失败：${err instanceof Error ? err.message : String(err)}`;\n            this.options.log(`[manager] ${id} 启动失败: ${err instanceof Error ? err.message : String(err)}`);\n            return { ok: false, error };\n        }\n    }\n    /**\n     * 停用并停止一个渠道（仅运行态，不持久化 enabled——重启后按配置自动恢复）。\n     * 彻底移除配置请用 {@link remove}。\n     */\n    async disconnect(id) {\n        const adapter = this.running.get(id);\n        if (adapter) {\n            await Promise.resolve(adapter.stop()).catch(() => undefined);\n            this.running.delete(id);\n            this.options.gateway.unregister(id);\n        }\n        this.options.log(`[manager] ${id} 已断开（配置保留，重启自动恢复）`);\n    }\n    /** 彻底移除渠道：停止并删除持久化配置（重启后不再自动连接）。 */\n    async remove(id) {\n        await this.cancelProvisioning(id);\n        await this.disconnect(id);\n        if (this.store[id]) {\n            delete this.store[id];\n            this.flush();\n        }\n        // 清空该渠道的授权与待授权\n        delete this.allowlist[id];\n        delete this.pending[id];\n        this.flush();\n        this.options.log(`[manager] ${id} 配置已删除`);\n    }\n    /** 刷新登录（重新启停，用于重新取二维码）。 */\n    async refreshLogin(id) {\n        await this.disconnect(id);\n        return this.connect(id);\n    }\n    /** 开始官方扫码创建/绑定机器人（飞书、QQ 等）。 */\n    async startProvisioning(id) {\n        const provisioner = provisionerFor(id);\n        if (!provisioner)\n            return { ok: false, error: `${CHANNEL_META[id]?.label ?? id} 暂不支持官方扫码接入` };\n        await this.cancelProvisioning(id);\n        const controller = new AbortController();\n        const attempt = { controller, status: '登录中' };\n        this.provisioning.set(id, attempt);\n        try {\n            const handle = await provisioner.start({\n                onQr: (qr) => {\n                    if (this.provisioning.get(id) !== attempt)\n                        return;\n                    attempt.qrDataUrl = qr.dataUrl;\n                    attempt.expiresAt = qr.expiresAt;\n                    attempt.status = '等待扫码';\n                },\n                onStatus: (status) => {\n                    if (this.provisioning.get(id) === attempt)\n                        attempt.status = status;\n                },\n                onCredentials: async (credentials) => {\n                    if (this.provisioning.get(id) !== attempt)\n                        return;\n                    attempt.status = '保存凭据';\n                    const owner = typeof credentials.ownerOpenId === 'string'\n                        ? credentials.ownerOpenId\n                        : typeof credentials.ownerUserOpenid === 'string' ? credentials.ownerUserOpenid : undefined;\n                    const config = { ...credentials };\n                    delete config.ownerOpenId;\n                    delete config.ownerUserOpenid;\n                    const result = await this.connect(id, config);\n                    if (result.ok) {\n                        if (owner)\n                            this.approve(id, owner);\n                        attempt.status = '已连接';\n                        attempt.qrDataUrl = undefined;\n                        attempt.expiresAt = undefined;\n                    }\n                    else {\n                        attempt.status = '连接失败';\n                        attempt.error = result.error;\n                    }\n                },\n                onFailure: (error) => {\n                    if (this.provisioning.get(id) !== attempt)\n                        return;\n                    const detail = error instanceof Error ? error.message : String(error);\n                    this.options.log(`[manager] ${id} 扫码失败: ${detail}`);\n                    attempt.status = controller.signal.aborted ? '已取消' : '扫码失败';\n                    attempt.error = controller.signal.aborted ? undefined : '平台扫码服务暂时不可用或二维码已过期，请重新扫码。';\n                },\n            }, controller.signal);\n            if (this.provisioning.get(id) === attempt)\n                attempt.handle = handle;\n            return { ok: true };\n        }\n        catch (error) {\n            const detail = error instanceof Error ? error.message : String(error);\n            this.options.log(`[manager] ${id} 扫码启动失败: ${detail}`);\n            if (this.provisioning.get(id) === attempt) {\n                attempt.status = '扫码启动失败';\n                attempt.error = '无法启动扫码流程，请检查网络和可选依赖后重试。';\n            }\n            return { ok: false, error: '无法启动扫码流程，请检查网络和可选依赖后重试。' };\n        }\n    }\n    /** 取消官方扫码接入尝试。 */\n    async cancelProvisioning(id) {\n        const attempt = this.provisioning.get(id);\n        if (!attempt)\n            return;\n        this.provisioning.delete(id);\n        attempt.controller.abort();\n        await Promise.resolve(attempt.handle?.cancel()).catch(() => undefined);\n    }\n    /** 渠道视图列表（UI 渲染用）。 */\n    list() {\n        const out = [];\n        for (const id of CHANNEL_IDS) {\n            const meta = CHANNEL_META[id];\n            const adapter = this.running.get(id);\n            const cfg = this.mergedConfig(id);\n            const provisioning = this.provisioning.get(id);\n            const rawStatus = adapter?.status?.();\n            const loginUrl = adapter?.loginUrl?.();\n            out.push({\n                id,\n                label: meta.label,\n                emoji: meta.emoji,\n                icon: meta.icon,\n                docs: meta.docs,\n                kind: meta.kind,\n                qrProvisioning: meta.qrProvisioning === true && provisionerFor(id) !== undefined,\n                provisioningStatus: provisioning?.status,\n                provisioningQrDataUrl: provisioning?.qrDataUrl,\n                provisioningExpiresAt: provisioning?.expiresAt,\n                provisioningError: provisioning?.error,\n                needs: meta.needs,\n                fields: meta.fields,\n                hint: meta.hint,\n                enabled: this.store[id]?.enabled === true || (cfg.enabled === true && !this.store[id]),\n                running: adapter !== undefined,\n                status: normalizeChannelStatus({\n                    running: adapter !== undefined,\n                    rawStatus,\n                    loginUrl,\n                    provisioningStatus: provisioning?.status,\n                }),\n                loginUrl,\n                configuredKeys: Object.keys(cfg).filter((k) => k !== 'enabled' && cfg[k] !== undefined && cfg[k] !== ''),\n                allowlist: this.allowlist[id] ?? [],\n            });\n        }\n        return out;\n    }\n    /** 注册 HTTP API（prefix 路由，由 webServer 提供）。 */\n    registerApi() {\n        const webServer = this.ctx.webServer;\n        if (!webServer)\n            return;\n        const send = (res, status, body) => {\n            res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });\n            res.end(JSON.stringify(body));\n        };\n        const readBody = (req) => new Promise((resolve) => {\n            let body = '';\n            req.on('data', (c) => { body += c; });\n            req.on('end', () => {\n                try {\n                    resolve(body ? JSON.parse(body) : {});\n                }\n                catch {\n                    resolve({});\n                }\n            });\n        });\n        this.apiDisposers.push(webServer.register({\n            kind: 'prefix',\n            path: '/dsh-im-gateway/api',\n            handler: async (req, res) => {\n                const url = new URL(req.url ?? '/', `http://${req.headers.host ?? 'localhost'}`);\n                const parts = url.pathname.split('/').filter(Boolean); // [dsh-im-gateway, api, ...]\n                // /dsh-im-gateway/api/icon/<channelId>：本地品牌图标（assets/icons/<meta.icon>），无外网依赖\n                if (parts[2] === 'icon' && parts.length === 4 && req.method === 'GET') {\n                    const channelId = parts[3];\n                    const icon = CHANNEL_META[channelId]?.icon;\n                    if (!icon) {\n                        send(res, 404, { ok: false, error: `no icon for ${channelId}` });\n                        return;\n                    }\n                    try {\n                        const buf = readFileSync(join(MODULE_DIR, '../assets/icons', icon));\n                        const ext = icon.includes('.') ? icon.slice(icon.lastIndexOf('.')) : '.svg';\n                        const contentType = ext === '.png' ? 'image/png' : ext === '.ico' ? 'image/x-icon' : 'image/svg+xml';\n                        res.writeHead(200, { 'content-type': `${contentType}; charset=utf-8`, 'cache-control': 'public, max-age=86400' });\n                        res.end(buf);\n                    }\n                    catch {\n                        send(res, 404, { ok: false, error: `icon file missing: ${icon}` });\n                    }\n                    return;\n                }\n                // /dsh-im-gateway/api/channels\n                if (parts[2] === 'channels' && parts.length === 3 && req.method === 'GET') {\n                    send(res, 200, { ok: true, channels: this.list(), pending: this.pendingRequests() });\n                    return;\n                }\n                // /dsh-im-gateway/api/cron\n                if (parts[2] === 'cron' && parts.length === 3 && req.method === 'GET') {\n                    send(res, 200, { ok: true, tasks: this.cron.list() });\n                    return;\n                }\n                if (parts[2] === 'cron' && parts.length === 4 && req.method === 'POST') {\n                    const id = parts[3];\n                    const body = await readBody(req);\n                    if (id === 'delete') {\n                        const removed = this.cron.remove(String(body.id ?? ''));\n                        send(res, removed ? 200 : 404, { ok: removed, ...(removed ? {} : { error: `任务不存在：${String(body.id ?? '')}` }) });\n                        return;\n                    }\n                    if (id === 'enable') {\n                        const enabled = body.enabled !== false;\n                        const done = this.cron.setEnabled(String(body.id ?? ''), enabled);\n                        send(res, done ? 200 : 404, { ok: done, ...(done ? { enabled } : { error: `任务不存在：${String(body.id ?? '')}` }) });\n                        return;\n                    }\n                    send(res, 404, { ok: false, error: `unknown cron action ${id}` });\n                    return;\n                }\n                // /dsh-im-gateway/api/channels/<id>/connect|disconnect|refresh\n                if (parts[2] === 'channels' && parts.length === 5) {\n                    const id = parts[3];\n                    const action = parts[4];\n                    if (req.method !== 'POST') {\n                        send(res, 405, { ok: false, error: 'method not allowed' });\n                        return;\n                    }\n                    const body = await readBody(req);\n                    if (action === 'connect') {\n                        const result = await this.connect(id, body.config);\n                        send(res, result.ok ? 200 : 400, result.ok ? { ok: true, channel: this.list().find((c) => c.id === id) } : { ok: false, error: result.error });\n                        return;\n                    }\n                    if (action === 'provision') {\n                        const result = await this.startProvisioning(id);\n                        send(res, result.ok ? 200 : 400, result.ok ? { ok: true, channel: this.list().find((c) => c.id === id) } : { ok: false, error: result.error });\n                        return;\n                    }\n                    if (action === 'cancel-provision') {\n                        await this.cancelProvisioning(id);\n                        send(res, 200, { ok: true, channel: this.list().find((c) => c.id === id) });\n                        return;\n                    }\n                    if (action === 'disconnect') {\n                        await this.disconnect(id);\n                        send(res, 200, { ok: true, channel: this.list().find((c) => c.id === id) });\n                        return;\n                    }\n                    if (action === 'remove') {\n                        await this.remove(id);\n                        send(res, 200, { ok: true, channel: this.list().find((c) => c.id === id) });\n                        return;\n                    }\n                    if (action === 'refresh') {\n                        const result = await this.refreshLogin(id);\n                        send(res, result.ok ? 200 : 400, result.ok ? { ok: true, channel: this.list().find((c) => c.id === id) } : { ok: false, error: result.error });\n                        return;\n                    }\n                    if (action === 'approve') {\n                        const userId = String(body.userId ?? '');\n                        if (!userId) {\n                            send(res, 400, { ok: false, error: '缺少 userId' });\n                            return;\n                        }\n                        this.approve(id, userId);\n                        send(res, 200, { ok: true, channel: this.list().find((c) => c.id === id) });\n                        return;\n                    }\n                    if (action === 'deny') {\n                        const userId = String(body.userId ?? '');\n                        if (!userId) {\n                            send(res, 400, { ok: false, error: '缺少 userId' });\n                            return;\n                        }\n                        this.deny(id, userId);\n                        send(res, 200, { ok: true, channel: this.list().find((c) => c.id === id) });\n                        return;\n                    }\n                    send(res, 404, { ok: false, error: `unknown action ${action}` });\n                    return;\n                }\n                send(res, 404, { ok: false, error: 'not found' });\n            },\n        }));\n        this.option